1	use anyhow::Result;
2	use cudarc::driver::CudaSlice;
3	use cudarc::driver::DevicePtr;
4	use cudarc::driver::DevicePtrMut;
5	use half::bf16;
6	
7	use crate::ffi;
8	use crate::paged_kv::KvFormat;
9	use crate::paged_kv::KvStorage;
10	use crate::paged_kv::PagedKvLayout;
11	use crate::paged_kv::derive_strides;
12	use crate::tensor::DeviceContext;
13	use crate::tensor::DeviceVec;
14	use crate::tensor::HiddenStates;
15	
16	/// GQA group sizes (query heads / KV heads) with a compiled FlashInfer
17	/// batch-decode kernel. This matches the set the pinned FlashInfer's
18	/// `DISPATCH_GQA_GROUP_SIZE` instantiates; a ratio outside it is not refused —
19	/// it takes the eager fallback — so this list gates an optimization, not
20	/// correctness. Keep it in step with the pinned FlashInfer.
21	pub const SUPPORTED_GQA_GROUP_SIZES: &[usize] = &[1, 2, 3, 4, 6, 8];
22	
23	// ============================================================================
24	// Paged prefill (FlashInfer BatchPrefillWithPagedKVCache)
25	// ============================================================================
26	
27	/// Pre-computed GPU metadata for paged prefill attention.
28	///
29	/// Built once per prefill call, shared across all layers.
30	/// Supports both single-request (`new`) and multi-request (`new_batch`) prefill.
31	pub struct PrefillPagedPlan {
32	    pub(super) page_indices_d: CudaSlice<i32>,
33	    pub(super) page_indptr_d: CudaSlice<i32>,
34	    pub(super) last_page_len_d: CudaSlice<i32>,
35	    pub(super) batch_indices_d: CudaSlice<i32>,
36	    positions_d: CudaSlice<i32>,
37	    pub(super) q_indptr_d: CudaSlice<i32>,
38	    /// The same boundaries the device copy holds, kept because a launcher
39	    /// that sizes its own grid needs them on the host and because the batch
40	    /// size is this vector's length, not a second thing to keep in step.
41	    /// Never empty: a plan with no requests still carries the leading zero.
42	    q_indptr_host: Vec<i32>,
43	    pub(super) request_indices_d: CudaSlice<i32>,
44	    pub(super) qo_tile_indices_d: CudaSlice<i32>,
45	    pub(super) kv_tile_indices_d: CudaSlice<i32>,
46	    pub(super) kv_chunk_size_d: CudaSlice<i32>,
47	    pub(super) total_num_rows_d: CudaSlice<u32>,
48	    pub(super) num_tiles: i32,
49	    pub(super) total_tokens: usize,
50	    cta_tile_q: i32,
51	    pub(super) head_dim: usize,
52	    pub(super) num_qo_heads: usize,
53	    pub(super) num_kv_heads: usize,
54	    pub(super) max_page_index: i32,
55	    pub(super) max_last_page_len: i32,
56	}
57	
58	/// GQA group size is an integer division by `num_kv_heads`, guarded by neither
59	/// the plan's tile arithmetic nor the C tile queries.
60	fn checked_head_relation(num_q_heads: usize, num_kv_heads: usize) -> Result<()> {
61	    anyhow::ensure!(
62	        num_kv_heads > 0 && num_q_heads > 0 && num_q_heads.is_multiple_of(num_kv_heads),
63	        "prefill plan num_q_heads {num_q_heads} must be a positive multiple of \
64	         num_kv_heads {num_kv_heads}"
65	    );
66	    Ok(())
67	}
68	
69	/// Largest page id and last-page length in the host inputs; the hd256 windowed
70	/// wrapper checks both against the pool geometry, which the kernels index with
71	/// no device-side bounds check.
72	fn checked_page_metadata(page_indices: &[i32], last_page_lens: &[i32]) -> Result<(i32, i32)> {
73	    let max_page_index = *page_indices
74	        .iter()
75	        .max()
76	        .ok_or_else(|| anyhow::anyhow!("prefill plan needs at least one page"))?;
77	    anyhow::ensure!(
78	        page_indices.iter().all(|&p| p >= 0),
79	        "prefill plan page indices must be non-negative"
80	    );
81	    let max_last_page_len = *last_page_lens
82	        .iter()
83	        .max()
84	        .ok_or_else(|| anyhow::anyhow!("prefill plan needs a last-page length"))?;
85	    anyhow::ensure!(
86	        last_page_lens.iter().all(|&l| l >= 1),
87	        "prefill plan last-page lengths must be at least 1"
88	    );
89	    Ok((max_page_index, max_last_page_len))
90	}
91	
92	impl PrefillPagedPlan {
93	    pub fn page_indices_d(&self) -> &CudaSlice<i32> {
94	        &self.page_indices_d
95	    }
96	    pub fn page_indptr_d(&self) -> &CudaSlice<i32> {
97	        &self.page_indptr_d
98	    }
99	    pub fn last_page_len_d(&self) -> &CudaSlice<i32> {
100	        &self.last_page_len_d
101	    }
102	    pub fn batch_indices_d(&self) -> &CudaSlice<i32> {
103	        &self.batch_indices_d
104	    }
105	    pub fn positions_d(&self) -> &CudaSlice<i32> {
106	        &self.positions_d
107	    }
108	    pub fn q_indptr_d(&self) -> &CudaSlice<i32> {
109	        &self.q_indptr_d
110	    }
111	    pub fn request_indices_d(&self) -> &CudaSlice<i32> {
112	        &self.request_indices_d
113	    }
114	    pub fn qo_tile_indices_d(&self) -> &CudaSlice<i32> {
115	        &self.qo_tile_indices_d
116	    }
117	    pub fn kv_tile_indices_d(&self) -> &CudaSlice<i32> {
118	        &self.kv_tile_indices_d
119	    }
120	    pub fn kv_chunk_size_d(&self) -> &CudaSlice<i32> {
121	        &self.kv_chunk_size_d
122	    }
123	    pub fn decode_metadata_d_mut(&mut self) -> (&mut CudaSlice<i32>, &mut CudaSlice<i32>) {
124	        (&mut self.last_page_len_d, &mut self.kv_chunk_size_d)
125	    }
126	    pub fn total_num_rows_d(&self) -> &CudaSlice<u32> {
127	        &self.total_num_rows_d
128	    }
129	    /// Derived, not stored: the boundaries already say how many requests
130	    /// there are, and a second field would be one more thing to keep in
131	    /// step. Saturating because an empty vector means no requests — the
132	    /// pre-allocated state — rather than a wrapped negative.
133	    pub fn batch_size(&self) -> i32 {
134	        self.q_indptr_host.len().saturating_sub(1) as i32
135	    }
136	
137	    /// The query boundaries, on the host. A caller that has to size a launch
138	    /// from them reads these rather than deriving the same walk again.
139	    pub fn q_indptr_host(&self) -> &[i32] {
140	        &self.q_indptr_host
141	    }
142	    pub fn num_tiles(&self) -> i32 {
143	        self.num_tiles
144	    }
145	    pub(super) fn cta_tile_q(&self) -> i32 {
146	        self.cta_tile_q
147	    }
148	
149	    #[allow(clippy::too_many_arguments)]
150	    pub fn new_with_cta_tile_q(
151	        ctx: &DeviceContext,
152	        page_indices_i32: &[i32],
153	        last_page_len: usize,
154	        start_pos: usize,
155	        seq_len: usize,
156	        num_q_heads: usize,
157	        num_kv_heads: usize,
158	        head_dim: usize,
159	        cta_tile_q_override: i32,
160	    ) -> Result<Self> {
161	        checked_head_relation(num_q_heads, num_kv_heads)?;
162	        let kv_len = start_pos + seq_len;
163	
164	        let last_page_len_i32 =
165	            crate::ops::checked_i32(last_page_len, "prefill plan last_page_len")?;
166	        let (max_page_index, max_last_page_len) =
167	            checked_page_metadata(page_indices_i32, &[last_page_len_i32])?;
168	        let num_pages_i32 =
169	            crate::ops::checked_i32(page_indices_i32.len(), "prefill plan page count")?;
170	        let seq_len_i32 = crate::ops::checked_i32(seq_len, "prefill plan seq_len")?;
171	        let start_pos_i32 = crate::ops::checked_i32(start_pos, "prefill plan start_pos")?;
172	        let kv_len_i32 = crate::ops::checked_i32(kv_len, "prefill plan kv length")?;
173	        let num_q_heads_i32 = crate::ops::checked_i32(num_q_heads, "prefill plan num_q_heads")?;
174	        let num_kv_heads_i32 = crate::ops::checked_i32(num_kv_heads, "prefill plan num_kv_heads")?;
175	        let head_dim_i32 = crate::ops::checked_i32(head_dim, "prefill plan head_dim")?;
176	        let total_rows_u32 = crate::ops::checked_u32(seq_len, "prefill plan seq_len")?;
177	        let page_indices_d = ctx.stream.clone_htod(page_indices_i32)?;
178	        let page_indptr_d = ctx.stream.clone_htod(&[0i32, num_pages_i32])?;
179	        let last_page_len_d = ctx.stream.clone_htod(&[last_page_len_i32])?;
180	
181	        let batch_indices_d = ctx.stream.clone_htod(&vec![0i32; seq_len])?;
182	        let positions: Vec<i32> = (start_pos_i32..kv_len_i32).collect();
183	        let positions_d = ctx.stream.clone_htod(&positions)?;
184	
185	        let num_tiles = unsafe {
186	            ffi::batch_prefill_paged_num_tiles_with_cta_tile_q(
187	                seq_len_i32,
188	                num_q_heads_i32,
189	                num_kv_heads_i32,
190	                head_dim_i32,
191	                cta_tile_q_override,
192	            )
193	        };
194	        anyhow::ensure!(
195	            num_tiles > 0,
196	            "invalid prefill CTA tile override {cta_tile_q_override}"
197	        );
198	        let cta_tile_q = unsafe {
199	            ffi::batch_prefill_cta_tile_q_with_override(
200	                seq_len_i32,
201	                num_q_heads_i32,
202	                num_kv_heads_i32,
203	                head_dim_i32,
204	                cta_tile_q_override,
205	            )
206	        };
207	        anyhow::ensure!(
208	            cta_tile_q > 0,
209	            "invalid prefill CTA tile override {cta_tile_q_override}"
210	        );
211	
212	        let q_indptr_host = vec![0i32, seq_len_i32];
213	        let q_indptr_d = ctx.stream.clone_htod(&q_indptr_host)?;
214	        let request_indices_d = ctx.stream.clone_htod(&vec![0i32; num_tiles as usize])?;
215	        let qo_tile_indices: Vec<i32> = (0..num_tiles).collect();
216	        let qo_tile_indices_d = ctx.stream.clone_htod(&qo_tile_indices)?;
217	        let kv_tile_indices_d = ctx.stream.clone_htod(&vec![0i32; num_tiles as usize])?;
218	        let kv_chunk_size_d = ctx.stream.clone_htod(&[kv_len_i32])?;
219	        let total_num_rows_d = ctx.stream.clone_htod(&[total_rows_u32])?;
220	
221	        Ok(Self {
222	            page_indices_d,
223	            page_indptr_d,
224	            last_page_len_d,
225	            batch_indices_d,
226	            positions_d,
227	            q_indptr_d,
228	            q_indptr_host,
229	            request_indices_d,
230	            qo_tile_indices_d,
231	            kv_tile_indices_d,
232	            kv_chunk_size_d,
233	            total_num_rows_d,
234	            num_tiles,
235	            total_tokens: seq_len,
236	            cta_tile_q,
237	            head_dim,
238	            num_qo_heads: num_q_heads,
239	            num_kv_heads,
240	            max_page_index,
241	            max_last_page_len,
242	        })
243	    }
