300	    /// Allocate a worst-case-sized plan once, to be refilled in place by
301	    /// [`Self::update_batch_with_cta_tile_q`]. Buffer pointers stay fixed across
302	    /// updates so a CUDA Graph captured against them remains valid on replay.
303	    /// Geometry starts unset; update before forward.
304	    pub fn new_preallocated(
305	        ctx: &DeviceContext,
306	        max_total_tokens: usize,
307	        max_total_pages: usize,
308	        max_batch: usize,
309	        max_tiles: usize,
310	    ) -> Result<Self> {
311	        Ok(Self {
312	            page_indices_d: ctx.stream.alloc_zeros(max_total_pages)?,
313	            page_indptr_d: ctx.stream.alloc_zeros(max_batch + 1)?,
314	            last_page_len_d: ctx.stream.alloc_zeros(max_batch)?,
315	            batch_indices_d: ctx.stream.alloc_zeros(max_total_tokens)?,
316	            positions_d: ctx.stream.alloc_zeros(max_total_tokens)?,
317	            q_indptr_d: ctx.stream.alloc_zeros(max_batch + 1)?,
318	            q_indptr_host: vec![0i32],
319	            request_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
320	            qo_tile_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
321	            kv_tile_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
322	            kv_chunk_size_d: ctx.stream.alloc_zeros(max_batch)?,
323	            total_num_rows_d: ctx.stream.alloc_zeros(1)?,
324	            num_tiles: 0,
325	            total_tokens: 0,
326	            cta_tile_q: 0,
327	            head_dim: 0,
328	            num_qo_heads: 0,
329	            num_kv_heads: 0,
330	            max_page_index: -1,
331	            max_last_page_len: 0,
332	        })
333	    }
