335	    /// Recompute the host-side batch metadata and `memcpy_htod` it into the
336	    /// pre-allocated device buffers (no allocation, no pointer change). The host
337	    /// computation is identical to [`Self::new_batch_with_cta_tile_q`]; only the
338	    /// upload differs (overwrite in place vs. fresh `clone_htod`).
339	    ///
340	    /// `memcpy_htod` copies `src.len()` elements and tolerates a larger
341	    /// destination, so the worst-case allocation may exceed the actual fill.
342	    #[allow(clippy::too_many_arguments)]
343	    pub fn update_batch_with_cta_tile_q(
344	        &mut self,
345	        ctx: &DeviceContext,
346	        page_indices: &[Vec<i32>],
347	        last_page_lens: &[usize],
348	        start_positions: &[usize],
349	        seq_lens: &[usize],
350	        num_q_heads: usize,
351	        num_kv_heads: usize,
352	        head_dim: usize,
353	        cta_tile_q_override: i32,
354	    ) -> Result<()> {
355	        let host = BatchPlanHost::compute(
356	            page_indices,
357	            last_page_lens,
358	            start_positions,
359	            seq_lens,
360	            num_q_heads,
361	            num_kv_heads,
362	            head_dim,
363	            cta_tile_q_override,
364	        )?;
365	
366	        let (max_page_index, max_last_page_len) =
367	            checked_page_metadata(&host.all_page_indices, &host.last_page_lens_i32)?;
368	        let cta_tile_q_i32 = crate::ops::checked_i32(host.cta_tile_q, "prefill plan cta_tile_q")?;
369	        let total_rows_u32 =
370	            crate::ops::checked_u32(host.total_tokens, "prefill plan total_tokens")?;
371	        anyhow::ensure!(
372	            host.all_page_indices.len() <= self.page_indices_d.len(),
373	            "verify plan page_indices ({}) exceeds preallocated capacity ({})",
374	            host.all_page_indices.len(),
375	            self.page_indices_d.len(),
376	        );
377	        anyhow::ensure!(
378	            host.page_indptr.len() <= self.page_indptr_d.len(),
379	            "verify plan page_indptr ({}) exceeds preallocated capacity ({})",
380	            host.page_indptr.len(),
381	            self.page_indptr_d.len(),
382	        );
383	        anyhow::ensure!(
384	            host.last_page_lens_i32.len() <= self.last_page_len_d.len(),
385	            "verify plan last_page_lens ({}) exceeds preallocated capacity ({})",
386	            host.last_page_lens_i32.len(),
387	            self.last_page_len_d.len(),
388	        );
389	        anyhow::ensure!(
390	            host.batch_indices.len() <= self.batch_indices_d.len(),
391	            "verify plan batch_indices ({}) exceeds preallocated capacity ({})",
392	            host.batch_indices.len(),
393	            self.batch_indices_d.len(),
394	        );
395	        anyhow::ensure!(
396	            host.positions.len() <= self.positions_d.len(),
397	            "verify plan positions ({}) exceeds preallocated capacity ({})",
398	            host.positions.len(),
399	            self.positions_d.len(),
400	        );
401	        anyhow::ensure!(
402	            host.q_indptr.len() <= self.q_indptr_d.len(),
403	            "verify plan q_indptr ({}) exceeds preallocated capacity ({})",
404	            host.q_indptr.len(),
405	            self.q_indptr_d.len(),
406	        );
407	        anyhow::ensure!(
408	            host.request_indices_v.len() <= self.request_indices_d.len(),
409	            "verify plan tiles ({}) exceeds preallocated capacity ({})",
410	            host.request_indices_v.len(),
411	            self.request_indices_d.len(),
412	        );
413	        anyhow::ensure!(
414	            host.kv_chunk_sizes.len() <= self.kv_chunk_size_d.len(),
415	            "verify plan kv_chunk_sizes ({}) exceeds preallocated capacity ({})",
416	            host.kv_chunk_sizes.len(),
417	            self.kv_chunk_size_d.len(),
418	        );
419	
420	        ctx.stream
421	            .memcpy_htod(&host.all_page_indices, &mut self.page_indices_d)?;
422	        ctx.stream
423	            .memcpy_htod(&host.page_indptr, &mut self.page_indptr_d)?;
424	        ctx.stream
425	            .memcpy_htod(&host.last_page_lens_i32, &mut self.last_page_len_d)?;
426	        ctx.stream
427	            .memcpy_htod(&host.batch_indices, &mut self.batch_indices_d)?;
428	        ctx.stream
429	            .memcpy_htod(&host.positions, &mut self.positions_d)?;
430	        self.q_indptr_host.clear();
431	        self.q_indptr_host.extend_from_slice(&host.q_indptr);
432	        ctx.stream
433	            .memcpy_htod(&self.q_indptr_host, &mut self.q_indptr_d)?;
434	        ctx.stream
435	            .memcpy_htod(&host.request_indices_v, &mut self.request_indices_d)?;
436	        ctx.stream
437	            .memcpy_htod(&host.qo_tile_indices_v, &mut self.qo_tile_indices_d)?;
438	        ctx.stream
439	            .memcpy_htod(&host.kv_tile_indices_v, &mut self.kv_tile_indices_d)?;
440	        ctx.stream
441	            .memcpy_htod(&host.kv_chunk_sizes, &mut self.kv_chunk_size_d)?;
442	        ctx.stream
443	            .memcpy_htod(&[total_rows_u32], &mut self.total_num_rows_d)?;
444	
445	        self.num_tiles = host.num_tiles;
446	        self.total_tokens = host.total_tokens;
447	        self.cta_tile_q = cta_tile_q_i32;
448	        self.head_dim = head_dim;
449	        self.num_qo_heads = num_q_heads;
450	        self.num_kv_heads = num_kv_heads;
451	        self.max_page_index = max_page_index;
452	        self.max_last_page_len = max_last_page_len;
453	        Ok(())
454	    }
455	}
