457	/// Host-side batch-prefill metadata, computed identically for the fresh
458	/// (`new_batch_with_cta_tile_q`) and in-place (`update_batch_with_cta_tile_q`)
459	/// paths so the two never diverge.
460	struct BatchPlanHost {
461	    all_page_indices: Vec<i32>,
462	    page_indptr: Vec<i32>,
463	    last_page_lens_i32: Vec<i32>,
464	    batch_indices: Vec<i32>,
465	    positions: Vec<i32>,
466	    q_indptr: Vec<i32>,
467	    request_indices_v: Vec<i32>,
468	    qo_tile_indices_v: Vec<i32>,
469	    kv_tile_indices_v: Vec<i32>,
470	    kv_chunk_sizes: Vec<i32>,
471	    num_tiles: i32,
472	    total_tokens: usize,
473	    cta_tile_q: usize,
474	}
475	
476	impl BatchPlanHost {
477	    #[allow(clippy::too_many_arguments)]
478	    fn compute(
479	        page_indices: &[Vec<i32>],
480	        last_page_lens: &[usize],
481	        start_positions: &[usize],
482	        seq_lens: &[usize],
483	        num_q_heads: usize,
484	        num_kv_heads: usize,
485	        head_dim: usize,
486	        cta_tile_q_override: i32,
487	    ) -> Result<Self> {
488	        checked_head_relation(num_q_heads, num_kv_heads)?;
489	        let batch_size = page_indices.len();
490	        assert_eq!(batch_size, last_page_lens.len());
491	        assert_eq!(batch_size, start_positions.len());
492	        assert_eq!(batch_size, seq_lens.len());
493	        let total_tokens: usize = seq_lens.iter().sum();
494	        let total_tokens_i32 = crate::ops::checked_i32(total_tokens, "prefill plan total_tokens")?;
495	        let num_q_heads_i32 = crate::ops::checked_i32(num_q_heads, "prefill plan num_q_heads")?;
496	        let num_kv_heads_i32 = crate::ops::checked_i32(num_kv_heads, "prefill plan num_kv_heads")?;
497	        let head_dim_i32 = crate::ops::checked_i32(head_dim, "prefill plan head_dim")?;
498	        let group_size = num_q_heads / num_kv_heads;
499	
500	        // Page metadata (concatenated across requests, CSR format)
501	        let mut all_page_indices = Vec::new();
502	        let mut page_indptr = vec![0i32];
503	        let mut last_page_lens_i32 = Vec::with_capacity(batch_size);
504	        let mut kv_chunk_sizes = Vec::with_capacity(batch_size);
505	
506	        for (i, pages) in page_indices.iter().enumerate() {
507	            anyhow::ensure!(
508	                !pages.is_empty(),
509	                "prefill plan request {i} has no pages; the attention kernels derive its KV \
510	                 length from its own page count and would give it none"
511	            );
512	            all_page_indices.extend_from_slice(pages);
513	            page_indptr.push(crate::ops::checked_i32(
514	                all_page_indices.len(),
515	                "prefill plan page-indptr entry",
516	            )?);
517	            last_page_lens_i32.push(crate::ops::checked_i32(
518	                last_page_lens[i],
519	                "prefill plan last_page_len",
520	            )?);
521	            kv_chunk_sizes.push(crate::ops::checked_i32(
522	                start_positions[i] + seq_lens[i],
523	                "prefill plan kv length",
524	            )?);
525	        }
526	
527	        // Per-token metadata
528	        let mut batch_indices = Vec::with_capacity(total_tokens);
529	        let mut positions = Vec::with_capacity(total_tokens);
530	        for (i, &seq_len) in seq_lens.iter().enumerate() {
531	            let start = start_positions[i];
532	            let request_i32 = crate::ops::checked_i32(i, "prefill plan request index")?;
533	            let start_i32 = crate::ops::checked_i32(start, "prefill plan start position")?;
534	            let end_i32 = crate::ops::checked_i32(start + seq_len, "prefill plan kv length")?;
535	            batch_indices.extend(std::iter::repeat_n(request_i32, seq_len));
536	            positions.extend(start_i32..end_i32);
537	        }
538	
539	        // Q token boundaries (CSR)
540	        let mut q_indptr = vec![0i32];
541	        for &seq_len in seq_lens {
542	            let prev = *q_indptr.last().unwrap();
543	            q_indptr.push(prev + crate::ops::checked_i32(seq_len, "prefill plan seq_len")?);
544	        }
545	
546	        // Tile plan: use global cta_tile_q for consistent tiling
547	        let cta_tile_q_i32 = unsafe {
548	            ffi::batch_prefill_cta_tile_q_with_override(
549	                total_tokens_i32,
550	                num_q_heads_i32,
551	                num_kv_heads_i32,
552	                head_dim_i32,
553	                cta_tile_q_override,
554	            )
555	        };
556	        anyhow::ensure!(
557	            cta_tile_q_i32 > 0,
558	            "invalid prefill CTA tile override {cta_tile_q_override}"
559	        );
560	        let cta_tile_q = cta_tile_q_i32 as usize;
561	
562	        let mut request_indices_v = Vec::new();
563	        let mut qo_tile_indices_v = Vec::new();
564	        let mut kv_tile_indices_v = Vec::new();
565	        for (req_idx, &seq_len) in seq_lens.iter().enumerate() {
566	            let packed_qo_len = seq_len * group_size;
567	            let num_tiles_req = packed_qo_len.div_ceil(cta_tile_q);
568	            let req_idx_i32 = crate::ops::checked_i32(req_idx, "prefill plan request index")?;
569	            let num_tiles_req_i32 =
570	                crate::ops::checked_i32(num_tiles_req, "prefill plan request tile count")?;
571	            for tile in 0..num_tiles_req_i32 {
572	                request_indices_v.push(req_idx_i32);
573	                qo_tile_indices_v.push(tile);
574	                kv_tile_indices_v.push(0i32);
575	            }
576	        }
577	        let num_tiles =
578	            crate::ops::checked_i32(request_indices_v.len(), "prefill plan tile count")?;
579	
580	        Ok(Self {
581	            all_page_indices,
582	            page_indptr,
583	            last_page_lens_i32,
584	            batch_indices,
585	            positions,
586	            q_indptr,
587	            request_indices_v,
588	            qo_tile_indices_v,
589	            kv_tile_indices_v,
590	            kv_chunk_sizes,
591	            num_tiles,
592	            total_tokens,
593	            cta_tile_q,
594	        })
595	    }
596	}
