598	/// Per-layer paged prefill: QK norm + RoPE, append K/V to paged, batch prefill attention.
599	///
600	/// Token positions (RoPE, scatter, attention) come from the plan's per-token
601	/// position array, so chunked or prefix-cached prefill (start > 0) works for
602	/// any batch size.
603	#[allow(clippy::too_many_arguments)]
604	pub fn prefill_attention_paged_into(
605	    ctx: &DeviceContext,
606	    q_batch: &mut HiddenStates,
607	    k_batch: &mut HiddenStates,
608	    v_batch: &HiddenStates,
609	    q_norm: &DeviceVec,
610	    k_norm: &DeviceVec,
611	    cos_cache: &DeviceVec,
612	    sin_cache: &DeviceVec,
613	    kv_buffer: &CudaSlice<bf16>,
614	    layout: &PagedKvLayout,
615	    layer: usize,
616	    plan: &PrefillPagedPlan,
617	    output: &mut HiddenStates,
618	    num_q_heads: usize,
619	    num_kv_heads: usize,
620	    head_dim: usize,
621	    rms_eps: f32,
622	) -> Result<()> {
623	    let total_tokens = plan.total_tokens;
624	    let kv_dim = num_kv_heads * head_dim;
625	    let sm_scale = 1.0f32 / (head_dim as f32).sqrt();
626	
627	    let PagedGeometry {
628	        k_offset_elems: k_offset,
629	        v_offset_elems: v_offset,
630	        stride_page,
631	        ..
632	    } = checked_paged_geometry(
633	        "paged prefill",
634	        layout,
635	        kv_buffer.len(),
636	        layer,
637	        head_dim,
638	        num_kv_heads,
639	        false,
640	    )?;
641	
642	    let (q_ptr, _gq) = q_batch.data.device_ptr_mut(&ctx.stream);
643	    let (k_ptr, _gk) = k_batch.data.device_ptr_mut(&ctx.stream);
644	    let (v_ptr, _gv) = v_batch.data.device_ptr(&ctx.stream);
645	    let (qn_ptr, _gqn) = q_norm.data.device_ptr(&ctx.stream);
646	    let (kn_ptr, _gkn) = k_norm.data.device_ptr(&ctx.stream);
647	    let (cos_ptr, _gc) = cos_cache.data.device_ptr(&ctx.stream);
648	    let (sin_ptr, _gs) = sin_cache.data.device_ptr(&ctx.stream);
649	    let (buf_ptr, _gbuf) = kv_buffer.device_ptr(&ctx.stream);
650	    let (o_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
651	    let (pi_ptr, _) = plan.page_indices_d.device_ptr(&ctx.stream);
652	    let (pip_ptr, _) = plan.page_indptr_d.device_ptr(&ctx.stream);
653	    let (lpl_ptr, _) = plan.last_page_len_d.device_ptr(&ctx.stream);
654	    let (bi_ptr, _) = plan.batch_indices_d.device_ptr(&ctx.stream);
655	    let (pos_ptr, _) = plan.positions_d.device_ptr(&ctx.stream);
656	    let (qi_ptr, _) = plan.q_indptr_d.device_ptr(&ctx.stream);
657	    let (ri_ptr, _) = plan.request_indices_d.device_ptr(&ctx.stream);
658	    let (qti_ptr, _) = plan.qo_tile_indices_d.device_ptr(&ctx.stream);
659	    let (kti_ptr, _) = plan.kv_tile_indices_d.device_ptr(&ctx.stream);
660	    let (kcs_ptr, _) = plan.kv_chunk_size_d.device_ptr(&ctx.stream);
661	    let (tnr_ptr, _) = plan.total_num_rows_d.device_ptr(&ctx.stream);
662	
663	    let stream = crate::tensor::active_cu_stream(ctx);
664	
665	    unsafe {
666	        // RoPE positions always come from the plan's per-token array — it is
667	        // the single source of truth for each token's absolute position. A
668	        // scalar-start_pos fast path for batch_size == 1 used to live here;
669	        // it silently rotated prefix-cache-hit suffixes from position 0 and
670	        // both entry points launch the same kernel anyway.
671	        ffi::qk_norm_rope_batched_decode_cuda(
672	            q_ptr as *mut ffi::Half,
673	            k_ptr as *mut ffi::Half,
674	            qn_ptr as *const ffi::Half,
675	            kn_ptr as *const ffi::Half,
676	            cos_ptr as *const ffi::Half,
677	            sin_ptr as *const ffi::Half,
