885	/// Validate a `[offset, offset + span)` row window into `t` and return the byte
886	/// offset of `offset`, all with checked arithmetic. Release builds leave
887	/// `overflow-checks` off, so an adversarial `offset` (e.g. `usize::MAX`) would
888	/// otherwise wrap the range check and the pointer past its allocation, faulting
889	/// only at the next sync as `CUDA_ERROR_ILLEGAL_ADDRESS`. Returns `Err`, never panics.
890	pub(crate) fn checked_row_offset(
891	    t: &HiddenStates,
892	    offset: usize,
893	    span: usize,
894	    name: &str,
895	) -> Result<u64> {
896	    let end = offset
897	        .checked_add(span)
898	        .ok_or_else(|| anyhow::anyhow!("{name} row range overflow"))?;
899	    anyhow::ensure!(
900	        end <= t.seq_len,
901	        "{name} row range [{offset}..{end}) exceeds seq_len {}",
902	        t.seq_len
903	    );
904	    t.checked_extent(name)?;
905	    let bytes = offset
906	        .checked_mul(t.hidden_dim)
907	        .and_then(|elems| elems.checked_mul(std::mem::size_of::<bf16>()))
908	        .ok_or_else(|| anyhow::anyhow!("{name} byte offset overflow"))?;
909	    Ok(bytes as u64)
910	}
