912	/// Plain RoPE (no QK-norm) for one EAGLE-3 draft step, because EAGLE-3 has no per-head q/k norm
913	/// we implement a new kernel for EAGLE-3
914	#[allow(clippy::too_many_arguments)]
915	pub fn eagle3_rope_into(
916	    ctx: &DeviceContext,
917	    q: &mut HiddenStates,
918	    q_row_offset: usize,
919	    q_seq_len: usize,
920	    k: &mut HiddenStates,
