925	    head_dim: usize,
926	    q_start_pos: usize,
927	    k_start_pos: usize,
928	) -> Result<()> {
929	    assert_eq!(q.hidden_dim, num_q_heads * head_dim);
930	    assert_eq!(k.hidden_dim, num_kv_heads * head_dim);
931	    // `q`/`k` are capacity-backed and reachable from safe re-exported code;
932	    // validate the row window and backing length before deriving raw pointers.
933	    let q_byte_offset = checked_row_offset(q, q_row_offset, q_seq_len, "eagle3_rope q")?;
