948	    let (k_ptr, _gk) = k.data.device_ptr_mut(&ctx.stream);
949	    let (cos_ptr, _gc) = cos_cache.data.device_ptr(&ctx.stream);
950	    let (sin_ptr, _gs) = sin_cache.data.device_ptr(&ctx.stream);
951	
952	    let result = unsafe {
953	        ffi::eagle3_rope_cuda(
954	            q_ptr as *mut ffi::Half,
955	            k_ptr as *mut ffi::Half,
956	            cos_ptr as *const ffi::Half,
957	            sin_ptr as *const ffi::Half,
958	            num_q_heads as i32,
959	            num_kv_heads as i32,
960	            head_dim as i32,
961	            q_seq_len as i32,
962	            k.seq_len as i32,
963	            q_start_pos as i32,
964	            k_start_pos as i32,
965	            (cos_cache.data.len() / head_dim) as i32,
966	            crate::tensor::active_cu_stream(ctx),
967	        )
968	    };
969	    if result != 0 {
970	        anyhow::bail!("eagle3_rope_cuda failed with error {result}");
971	    }
972	    Ok(())
973	}
