1012	/// Non-causal attention over a contiguous range of the request's KV cache.
1013	/// All queries see the same range. DFlash2 uses this for its anchor-relative
1014	/// context window plus the complete draft block, including future mask slots.
1015	#[allow(clippy::too_many_arguments)]
1016	pub fn single_prefill_nhd_noncausal_range_into(
1017	    ctx: &DeviceContext,
1018	    q: &HiddenStates,
1019	    row_offset: usize,
1020	    q_seq_len: usize,
1021	    k_cache: &HiddenStates,
1022	    v_cache: &HiddenStates,
1023	    output: &mut HiddenStates,
1024	    num_q_heads: usize,
1025	    num_kv_heads: usize,
1026	    head_dim: usize,
1027	    kv_rows: std::ops::Range<usize>,
1028	) -> Result<()> {
1029	    assert_eq!(q.hidden_dim, num_q_heads * head_dim);
1030	    assert_eq!(output.hidden_dim, q.hidden_dim);
1031	    assert_eq!(output.seq_len, q.seq_len);
1032	    assert_eq!(k_cache.hidden_dim, num_kv_heads * head_dim);
1033	    assert_eq!(v_cache.hidden_dim, k_cache.hidden_dim);
1034	    assert_eq!(v_cache.seq_len, k_cache.seq_len);
1035	    assert!(kv_rows.start < kv_rows.end && kv_rows.end <= k_cache.seq_len);
1036	    let kv_len = kv_rows.end - kv_rows.start;
1037	    assert!(
1038	        row_offset + q_seq_len <= q.seq_len,
1039	        "single_prefill row range [{}..{}) exceeds seq_len {}",
1040	        row_offset,
1041	        row_offset + q_seq_len,
1042	        q.seq_len
1043	    );
1044	
1045	    // q and output share row_offset (asserted same seq_len/hidden_dim above).
1046	    let byte_offset = (row_offset * q.hidden_dim * std::mem::size_of::<bf16>()) as u64;
1047	    let (q_ptr, _gq) = q.data.device_ptr(&ctx.stream);
1048	    let q_ptr = q_ptr + byte_offset;
1049	    let (k_ptr, _gk) = k_cache.data.device_ptr(&ctx.stream);
1050	    let (v_ptr, _gv) = v_cache.data.device_ptr(&ctx.stream);
1051	    let kv_offset = (kv_rows.start * k_cache.hidden_dim * std::mem::size_of::<bf16>()) as u64;
1052	    let k_ptr = k_ptr + kv_offset;
1053	    let v_ptr = v_ptr + kv_offset;
1054	    let (out_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
1055	    let out_ptr = out_ptr + byte_offset;
1056	    // FlashInfer's prefill kernel is a compile-time HEAD_DIM template: 128 is
1057	    // the Qwen3 DFlash drafter, 64 the GLM5.2 DSpark drafter.
1058	    let kernel = match head_dim {
1059	        128 => ffi::single_prefill_nhd_noncausal_cuda,
1060	        64 => ffi::single_prefill_nhd_noncausal_cuda_hd64,
1061	        other => anyhow::bail!(
1062	            "single_prefill_nhd_noncausal has no head_dim {other} instantiation (64/128 only)"
1063	        ),
1064	    };
1065	    let result = unsafe {
1066	        kernel(
1067	            q_ptr as *const ffi::Half,
1068	            out_ptr as *mut ffi::Half,
1069	            k_ptr as *const ffi::Half,
1070	            v_ptr as *const ffi::Half,
1071	            num_q_heads as i32,
1072	            num_kv_heads as i32,
1073	            head_dim as i32,
1074	            q_seq_len as i32,
1075	            kv_len as i32,
1076	            (k_cache.seq_len - kv_rows.start) as i32,
1077	            1.0f32 / (head_dim as f32).sqrt(),
1078	            crate::tensor::active_cu_stream(ctx),
1079	        )
1080	    };
1081	    if result != 0 {
1082	        anyhow::bail!(
1083	            "single_prefill_nhd_noncausal_cuda failed with error {result}{}",
1084	            crate::ops::ffi_exception_message(result)
1085	        );
1086	    }
1087	    Ok(())
1088	}
