1181	        q_seq_len <= kv_len,
1182	        "causal prefill q_seq_len {q_seq_len} exceeds kv_len {kv_len}"
1183	    );
1184	    // Validate the row window with checked arithmetic and every backing
1185	    // allocation before deriving pointers; `q`/`output` share the row sub-range.
1186	    let byte_offset = checked_row_offset(q, row_offset, q_seq_len, "single_prefill_causal q")?;
1187	    output.checked_extent("single_prefill_causal output")?;
1188	    k_cache.checked_extent("single_prefill_causal k_cache")?;
1189	    v_cache.checked_extent("single_prefill_causal v_cache")?;
1190	    let (q_ptr, _gq) = q.data.device_ptr(&ctx.stream);
1191	    let q_ptr = q_ptr + byte_offset;
1192	    let (k_ptr, _gk) = k_cache.data.device_ptr(&ctx.stream);
1193	    let (v_ptr, _gv) = v_cache.data.device_ptr(&ctx.stream);
1194	    let (out_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
1195	    let out_ptr = out_ptr + byte_offset;
1196	    let result = unsafe {
1197	        ffi::single_prefill_nhd_causal_cuda(
1198	            q_ptr as *const ffi::Half,
1199	            out_ptr as *mut ffi::Half,
1200	            k_ptr as *const ffi::Half,
1201	            v_ptr as *const ffi::Half,
1202	            num_q_heads as i32,
1203	            num_kv_heads as i32,
1204	            head_dim as i32,
1205	            q_seq_len as i32,
1206	            kv_len as i32,
1207	            k_cache.seq_len as i32,
1208	            1.0f32 / (head_dim as f32).sqrt(),
1209	            crate::tensor::active_cu_stream(ctx),
1210	        )
1211	    };
1212	    if result != 0 {
1213	        anyhow::bail!(
1214	            "single_prefill_nhd_causal_cuda failed with error {result}{}",
1215	            crate::ops::ffi_exception_message(result)
1216	        );
1217	    }
1218	    Ok(())
1219	}
