1221	/// Batched paged attention decode: append K/V + FlashInfer BatchDecode for batch_size >= 1.
1222	///
1223	/// Q: HiddenStates [q_dim, batch_size], output: HiddenStates [q_dim, batch_size].
1224	/// Metadata arrays are concatenated across requests (CSR format).
1225	#[allow(clippy::too_many_arguments)]
1226	pub fn paged_attention_batch_decode_into(
1227	    ctx: &DeviceContext,
1228	    q: &HiddenStates,
1229	    k: &HiddenStates,
1230	    v: &HiddenStates,
1231	    kv_buffer: &CudaSlice<bf16>,
1232	    layout: &PagedKvLayout,
1233	    layer: usize,
1234	    page_indices_d: &CudaSlice<i32>,
1235	    page_indptr_d: &CudaSlice<i32>,
1236	    last_page_len_d: &CudaSlice<i32>,
1237	    positions_d: &CudaSlice<i32>,
1238	    request_indices_d: &CudaSlice<i32>,
1239	    kv_tile_indices_d: &CudaSlice<i32>,
1240	    kv_chunk_size_d: &CudaSlice<i32>,
1241	    output: &mut HiddenStates,
1242	    num_qo_heads: usize,
1243	    batch_size: usize,
1244	) -> Result<()> {
1245	    let num_kv_heads = layout.num_kv_heads;
1246	    let head_dim = layout.head_dim;
1247	    let page_size = layout.page_size;
1248	
1249	    let PagedGeometry {
1250	        k_offset_elems: k_offset,
1251	        v_offset_elems: v_offset,
1252	        stride_page,
1253	        ..
1254	    } = checked_paged_geometry(
1255	        "batch decode",
1256	        layout,
1257	        kv_buffer.len(),
1258	        layer,
1259	        head_dim,
1260	        num_kv_heads,
1261	        false,
1262	    )?;
1263	
1264	    let (buf_ptr, _gbuf) = kv_buffer.device_ptr(&ctx.stream);
1265	    let (q_ptr, _gq) = q.data.device_ptr(&ctx.stream);
1266	    let (k_ptr, _gk) = k.data.device_ptr(&ctx.stream);
1267	    let (v_ptr, _gv) = v.data.device_ptr(&ctx.stream);
1268	    let (out_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
1269	    let (pi_ptr, _gpi) = page_indices_d.device_ptr(&ctx.stream);
1270	    let (pip_ptr, _gpip) = page_indptr_d.device_ptr(&ctx.stream);
1271	    let (lpl_ptr, _glpl) = last_page_len_d.device_ptr(&ctx.stream);
1272	    let (pos_ptr, _gpos) = positions_d.device_ptr(&ctx.stream);
1273	    let (ri_ptr, _gri) = request_indices_d.device_ptr(&ctx.stream);
1274	    let (kti_ptr, _gkti) = kv_tile_indices_d.device_ptr(&ctx.stream);
1275	    let (kcs_ptr, _gkcs) = kv_chunk_size_d.device_ptr(&ctx.stream);
1276	
1277	    let stream = crate::tensor::active_cu_stream(ctx);
1278	
1279	    // Step 1: Append K/V to paged cache (batched) using the same generic
1280	    // scatter path as prefill, with explicit request indices and positions.
1281	    let src_stride_n = (num_kv_heads * head_dim) as i64;
1282	    let src_stride_h = head_dim as i64;
1283	    let result = unsafe {
1284	        ffi::paged_kv_scatter_cuda(
1285	            buf_ptr as *const ffi::Half,
1286	            k_offset,
1287	            v_offset,
1288	            pi_ptr as *const i32,
1289	            pip_ptr as *const i32,
1290	            lpl_ptr as *const i32,
1291	            k_ptr as *const ffi::Half,
1292	            v_ptr as *const ffi::Half,
1293	            ri_ptr as *const i32,
1294	            pos_ptr as *const i32,
1295	            batch_size as i32,
1296	            num_kv_heads as i32,
1297	            head_dim as i32,
1298	            page_size as i32,
1299	            stride_page,
1300	            src_stride_n,
1301	            src_stride_h,
1302	            stream,
1303	        )
1304	    };
1305	    if result != 0 {
1306	        anyhow::bail!(
1307	            "paged_kv_scatter_cuda (batch decode) failed with error {result}{}",
1308	            crate::ops::ffi_exception_message(result)
1309	        );
1310	    }
1311	
1312	    // Step 2: Paged attention decode (batched)
1313	    let sm_scale = 1.0f32 / (head_dim as f32).sqrt();
1314	    let result = unsafe {
1315	        ffi::paged_attention_decode_cuda(
1316	            q_ptr as *const ffi::Half,
1317	            out_ptr as *mut ffi::Half,
1318	            buf_ptr as *const ffi::Half,
1319	            k_offset,
1320	            v_offset,
1321	            pi_ptr as *const i32,
1322	            pip_ptr as *const i32,
1323	            lpl_ptr as *const i32,
1324	            ri_ptr as *const i32,
1325	            kti_ptr as *const i32,
1326	            kcs_ptr as *const i32,
1327	            num_qo_heads as i32,
1328	            num_kv_heads as i32,
1329	            head_dim as i32,
1330	            page_size as i32,
1331	            batch_size as i32,
1332	            stride_page,
1333	            sm_scale,
1334	            stream,
1335	        )
1336	    };
1337	    if result != 0 {
1338	        anyhow::bail!(
1339	            "paged_attention_decode_cuda (batch) failed with error {result}{}",
1340	            crate::ops::ffi_exception_message(result)
1341	        );
1342	    }
1343	
1344	    Ok(())
1345	}
