1348	///
1349	/// This is intended for low-batch, long-context decode where the non-partition
1350	/// grid `(batch, kv_heads)` does not expose enough CTAs.
1351	///
1352	/// Q/K/V/output are read and written over `[row_offset, row_offset + batch_size)`; every paged and
1353	/// split-KV metadata array is indexed from local row 0.
1354	#[allow(clippy::too_many_arguments)]
1355	pub fn paged_attention_batch_decode_split_kv_into(
1356	    ctx: &DeviceContext,
1357	    q: &HiddenStates,
1358	    k: &HiddenStates,
1359	    v: &HiddenStates,
1360	    row_offset: usize,
1361	    kv_buffer: &CudaSlice<bf16>,
1362	    layout: &PagedKvLayout,
1363	    layer: usize,
1364	    page_indices_d: &CudaSlice<i32>,
1365	    page_indptr_d: &CudaSlice<i32>,
1366	    last_page_len_d: &CudaSlice<i32>,
1367	    positions_d: &CudaSlice<i32>,
1368	    request_indices_d: &CudaSlice<i32>,
1369	    split_request_indices_d: &CudaSlice<i32>,
1370	    split_kv_tile_indices_d: &CudaSlice<i32>,
1371	    split_kv_chunk_size_d: &CudaSlice<i32>,
1372	    split_o_indptr_d: &CudaSlice<i32>,
1373	    split_block_valid_mask_d: &CudaSlice<u8>,
1374	    split_tmp_v: &mut CudaSlice<bf16>,
1375	    split_tmp_s: &mut CudaSlice<f32>,
1376	    split_padded_slots: usize,
1377	    output: &mut HiddenStates,
1378	    num_qo_heads: usize,
1379	    batch_size: usize,
1380	) -> Result<()> {
1381	    let q_byte_offset = checked_row_offset(
1382	        q,
1383	        row_offset,
1384	        batch_size,
1385	        "paged_attention_batch_decode_split_kv q",
1386	    )?;
1387	    let k_byte_offset = checked_row_offset(
1388	        k,
1389	        row_offset,
1390	        batch_size,
1391	        "paged_attention_batch_decode_split_kv k",
1392	    )?;
1393	    let v_byte_offset = checked_row_offset(
1394	        v,
1395	        row_offset,
1396	        batch_size,
1397	        "paged_attention_batch_decode_split_kv v",
1398	    )?;
1399	    let out_byte_offset = checked_row_offset(
1400	        output,
1401	        row_offset,
1402	        batch_size,
1403	        "paged_attention_batch_decode_split_kv output",
1404	    )?;
1405	
1406	    let num_kv_heads = layout.num_kv_heads;
1407	    let head_dim = layout.head_dim;
1408	    let page_size = layout.page_size;
1409	
1410	    let PagedGeometry {
1411	        k_offset_elems: k_offset,
1412	        v_offset_elems: v_offset,
1413	        stride_page,
1414	        ..
1415	    } = checked_paged_geometry(
1416	        "batch split-K decode",
1417	        layout,
1418	        kv_buffer.len(),
1419	        layer,
1420	        head_dim,
1421	        num_kv_heads,
1422	        false,
1423	    )?;
1424	
1425	    let (buf_ptr, _gbuf) = kv_buffer.device_ptr(&ctx.stream);
1426	    let (q_ptr, _gq) = q.data.device_ptr(&ctx.stream);
1427	    let q_ptr = q_ptr + q_byte_offset;
1428	    let (k_ptr, _gk) = k.data.device_ptr(&ctx.stream);
1429	    let k_ptr = k_ptr + k_byte_offset;
1430	    let (v_ptr, _gv) = v.data.device_ptr(&ctx.stream);
1431	    let v_ptr = v_ptr + v_byte_offset;
1432	    let (out_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
1433	    let out_ptr = out_ptr + out_byte_offset;
1434	    let (pi_ptr, _gpi) = page_indices_d.device_ptr(&ctx.stream);
1435	    let (pip_ptr, _gpip) = page_indptr_d.device_ptr(&ctx.stream);
1436	    let (lpl_ptr, _glpl) = last_page_len_d.device_ptr(&ctx.stream);
1437	    let (pos_ptr, _gpos) = positions_d.device_ptr(&ctx.stream);
1438	    let (ri_ptr, _gri) = request_indices_d.device_ptr(&ctx.stream);
1439	    let (split_ri_ptr, _gsri) = split_request_indices_d.device_ptr(&ctx.stream);
1440	    let (split_kti_ptr, _gskti) = split_kv_tile_indices_d.device_ptr(&ctx.stream);
1441	    let (split_kcs_ptr, _gskcs) = split_kv_chunk_size_d.device_ptr(&ctx.stream);
1442	    let (split_o_indptr_ptr, _gsoi) = split_o_indptr_d.device_ptr(&ctx.stream);
1443	    let (split_valid_ptr, _gsv) = split_block_valid_mask_d.device_ptr(&ctx.stream);
1444	    let (split_tmp_v_ptr, _gstmpv) = split_tmp_v.device_ptr_mut(&ctx.stream);
1445	    let (split_tmp_s_ptr, _gstmps) = split_tmp_s.device_ptr_mut(&ctx.stream);
1446	
1447	    let stream = crate::tensor::active_cu_stream(ctx);
1448	
1449	    let src_stride_n = (num_kv_heads * head_dim) as i64;
1450	    let src_stride_h = head_dim as i64;
1451	    let result = unsafe {
1452	        ffi::paged_kv_scatter_cuda(
1453	            buf_ptr as *const ffi::Half,
1454	            k_offset,
1455	            v_offset,
1456	            pi_ptr as *const i32,
1457	            pip_ptr as *const i32,
1458	            lpl_ptr as *const i32,
1459	            k_ptr as *const ffi::Half,
1460	            v_ptr as *const ffi::Half,
1461	            ri_ptr as *const i32,
1462	            pos_ptr as *const i32,
1463	            batch_size as i32,
1464	            num_kv_heads as i32,
1465	            head_dim as i32,
1466	            page_size as i32,
1467	            stride_page,
1468	            src_stride_n,
1469	            src_stride_h,
1470	            stream,
1471	        )
1472	    };
1473	    if result != 0 {
1474	        anyhow::bail!(
1475	            "paged_kv_scatter_cuda (batch split-K decode) failed with error {result}{}",
1476	            crate::ops::ffi_exception_message(result)
1477	        );
1478	    }
1479	
1480	    let sm_scale = 1.0f32 / (head_dim as f32).sqrt();
1481	    let result = unsafe {
1482	        ffi::paged_attention_decode_split_kv_cuda(
1483	            q_ptr as *const ffi::Half,
1484	            out_ptr as *mut ffi::Half,
1485	            buf_ptr as *const ffi::Half,
1486	            k_offset,
1487	            v_offset,
1488	            pi_ptr as *const i32,
1489	            pip_ptr as *const i32,
1490	            lpl_ptr as *const i32,
1491	            split_ri_ptr as *const i32,
1492	            split_kti_ptr as *const i32,
1493	            split_kcs_ptr as *const i32,
1494	            split_o_indptr_ptr as *const i32,
1495	            split_valid_ptr as *const u8,
1496	            split_tmp_v_ptr as *mut ffi::Half,
1497	            split_tmp_s_ptr as *mut f32,
1498	            num_qo_heads as i32,
1499	            num_kv_heads as i32,
1500	            head_dim as i32,
1501	            page_size as i32,
1502	            batch_size as i32,
1503	            split_padded_slots as i32,
1504	            stride_page,
1505	            sm_scale,
1506	            stream,
1507	        )
1508	    };
1509	    if result != 0 {
1510	        anyhow::bail!(
1511	            "paged_attention_decode_split_kv_cuda (batch) failed with error {result}{}",
1512	            crate::ops::ffi_exception_message(result)
1513	        );
1514	    }
1515	
1516	    Ok(())
1517	}
1518	
1519	/// Everything a paged-pool launch (prep write or attention read) derives
1520	/// from a caller-supplied `PagedKvLayout`, re-derived with overflow checks
1521	/// and narrowed through
1522	/// checked conversions: the layout's fields are public, so a contradictory
1523	/// or wrapping layout must fail here, before anything reaches an unsafe
1524	/// launch.
1525	pub(super) struct PagedGeometry {
1526	    pub(super) k_offset_elems: i64,
1527	    pub(super) v_offset_elems: i64,
1528	    #[cfg_attr(not(feature = "gemma4"), allow(dead_code))]
1529	    pub(super) page_size: i32,
1530	    #[cfg_attr(not(feature = "gemma4"), allow(dead_code))]
1531	    pub(super) num_pages: i32,
1532	    pub(super) stride_page: i64,
1533	}
1534	
1535	pub(super) fn checked_paged_geometry(
1536	    what: &str,
1537	    layout: &PagedKvLayout,
1538	    pool_len: usize,
1539	    layer: usize,
1540	    head_dim: usize,
1541	    num_kv_heads: usize,
1542	    fp8_capable: bool,
1543	) -> Result<PagedGeometry> {
1544	    // This is the split geometry: a K block and a V block per layer, which
1545	    // is what FlashInfer's paged view and the prep scatter address through
1546	    // `k_offset`/`v_offset`. Neither can express another format, so one is
1547	    // refused here rather than read at the wrong rows.
1548	    anyhow::ensure!(
1549	        layout.format == KvFormat::Split,
1550	        "{what} reads the split K|V format; the layout is {:?}",
1551	        layout.format
1552	    );
1553	    // `pool_len` counts the pool's bf16 backing slots; an e4m3 pool packs two
1554	    // elements per slot. Only wrappers with an fp8 kernel twin may see one.
1555	    anyhow::ensure!(
1556	        fp8_capable || layout.storage == KvStorage::Bf16,
1557	        "{what} has no fp8 KV path; the layout carries {}-byte elements",
1558	        layout.storage.elem_bytes()
1559	    );
1560	    let pool_len = match layout.storage {
1561	        KvStorage::E4m3 => pool_len
1562	            .checked_mul(2)
1563	            .ok_or_else(|| anyhow::anyhow!("{what} fp8 pool element count overflows"))?,
1564	        KvStorage::Bf16 => pool_len,
1565	    };
1566	    anyhow::ensure!(
1567	        layout.head_dim == head_dim,
1568	        "{what} layout.head_dim {} != {head_dim}",
1569	        layout.head_dim
1570	    );
1571	    anyhow::ensure!(
1572	        layout.num_kv_heads == num_kv_heads,
1573	        "{what} layout.num_kv_heads {} != num_kv_heads {num_kv_heads}",
1574	        layout.num_kv_heads
1575	    );
1576	    // A zero head_dim makes every stride zero, and `pool_len / page_stride`
1577	    // below would panic on a layout that is otherwise self-consistent.
1578	    anyhow::ensure!(
1579	        layout.page_size > 0
1580	            && layout.num_kv_heads > 0
1581	            && layout.num_layers > 0
1582	            && layout.head_dim > 0,
1583	        "{what} layout dims must be positive: page_size {} num_kv_heads {} num_layers {} \
1584	         head_dim {}",
1585	        layout.page_size,
1586	        layout.num_kv_heads,
1587	        layout.num_layers,
1588	        layout.head_dim
1589	    );
1590	    // The layout's fields are public, so its strides are re-derived from its
1591	    // primitives and held to what it carries -- through the one derivation
1592	    // the layout itself uses, not a second statement of the arithmetic.
1593	    let (kv_block_len, layer_stride, page_stride) = derive_strides(
1594	        layout.page_size,
1595	        layout.num_kv_heads,
1596	        layout.head_dim,
1597	        layout.num_layers,
1598	        layout.format,
1599	    )
1600	    .ok_or_else(|| {
1601	        anyhow::anyhow!(
1602	            "{what} strides overflow: page_size {} num_kv_heads {} head_dim {} num_layers {}",
1603	            layout.page_size,
1604	            layout.num_kv_heads,
1605	            layout.head_dim,
1606	            layout.num_layers
1607	        )
1608	    })?;
1609	    anyhow::ensure!(
1610	        layout.kv_block_len == kv_block_len,
1611	        "{what} layout.kv_block_len {} != page_size * num_kv_heads * head_dim {kv_block_len}",
1612	        layout.kv_block_len
1613	    );
1614	    anyhow::ensure!(
1615	        layout.layer_stride == layer_stride,
1616	        "{what} layout.layer_stride {} != the format's {layer_stride}",
1617	        layout.layer_stride
1618	    );
1619	    anyhow::ensure!(
1620	        layout.page_stride == page_stride,
1621	        "{what} layout.page_stride {} != num_layers {} * layer_stride {layer_stride}",
1622	        layout.page_stride,
1623	        layout.num_layers
1624	    );
1625	    anyhow::ensure!(
1626	        layer < layout.num_layers,
1627	        "{what} layer {layer} >= layout.num_layers {}",
1628	        layout.num_layers
1629	    );
1630	    anyhow::ensure!(
1631	        pool_len.is_multiple_of(page_stride),
1632	        "{what} kv_pool.len {pool_len} is not a multiple of layout.page_stride {page_stride}"
1633	    );
1634	    let num_pages = pool_len / page_stride;
1635	    anyhow::ensure!(
1636	        num_pages >= 1,
1637	        "{what} kv_pool.len {pool_len} holds no whole page (page_stride {page_stride})"
1638	    );
1639	    let k_offset = layer.checked_mul(layer_stride).ok_or_else(|| {
1640	        anyhow::anyhow!("{what} layer {layer} * layer_stride {layer_stride} overflows")
1641	    })?;
1642	    let v_offset = k_offset.checked_add(kv_block_len).ok_or_else(|| {
1643	        anyhow::anyhow!("{what} K offset {k_offset} + kv_block_len {kv_block_len} overflows")
1644	    })?;
1645	    Ok(PagedGeometry {
1646	        k_offset_elems: i64::try_from(k_offset)
1647	            .map_err(|_| anyhow::anyhow!("{what} K offset {k_offset} does not fit i64"))?,
1648	        v_offset_elems: i64::try_from(v_offset)
1649	            .map_err(|_| anyhow::anyhow!("{what} V offset {v_offset} does not fit i64"))?,
1650	        page_size: crate::ops::checked_i32(layout.page_size, "paged prep page_size")?,
1651	        num_pages: crate::ops::checked_i32(num_pages, "paged prep num_pages")?,
1652	        stride_page: i64::try_from(page_stride)
1653	            .map_err(|_| anyhow::anyhow!("{what} page_stride {page_stride} does not fit i64"))?,
1654	    })
1655	}
