89	    for (int o = WARP_SIZE / 2; o > 0; o >>= 1)
90	        sq += __shfl_xor_sync(0xffffffff, sq, o);
91	    const float inv_rms = rsqrtf(sq / head_dim + eps);
92	
93	    float normed[4];
94	    #pragma unroll
95	    for (int r = 0; r < 4; r++) {
96	        __nv_bfloat16 n = __float2bfloat16(val[r] * inv_rms);
97	        float nf = __bfloat162float(n) * __bfloat162float(wb[r]);
98	        normed[r] = __bfloat162float(__float2bfloat16(nf));
99	    }
100	
101	    // Rotate-half partner: lane^16 maps d0 <-> d0 ± half.
102	    float partner[4];
103	    #pragma unroll
104	    for (int r = 0; r < 4; r++)
105	        partner[r] = __shfl_xor_sync(0xffffffff, normed[r], 16);
106	
107	    __nv_bfloat16 out[4];
108	    #pragma unroll
109	    for (int r = 0; r < 4; r++) {
110	        float c = __bfloat162float(cb[r]);
111	        float s = __bfloat162float(sb[r]);
112	        if (low) {
113	            float lo_cos = __bfloat162float(__float2bfloat16(normed[r] * c));
114	            float hi_sin = __bfloat162float(__float2bfloat16(partner[r] * s));
115	            out[r] = __float2bfloat16(lo_cos - hi_sin);
116	        } else {
117	            float lo_sin = __bfloat162float(__float2bfloat16(partner[r] * s));
118	            float hi_cos = __bfloat162float(__float2bfloat16(normed[r] * c));
119	            out[r] = __float2bfloat16(lo_sin + hi_cos);
120	        }
121	    }
122	    *reinterpret_cast<float2*>(&data[base]) = *reinterpret_cast<float2*>(out);
123	}
