125	__global__ void dflash_qk_norm_rope_kernel(
126	    __nv_bfloat16* __restrict__ q,
127	    __nv_bfloat16* __restrict__ k,
128	    const __nv_bfloat16* __restrict__ q_norm_weight,
129	    const __nv_bfloat16* __restrict__ k_norm_weight,
130	    const __nv_bfloat16* __restrict__ cos_cache,
131	    const __nv_bfloat16* __restrict__ sin_cache,
132	    int num_q_heads,
133	    int num_kv_heads,
134	    int head_dim,
135	    int q_len,
136	    int k_len,
137	    int q_start_pos,
138	    int k_start_pos,
139	    float eps,
140	    int cos_max_pos
141	) {
142	    int head_global = blockIdx.x;
143	    int token = blockIdx.y;
144	    int d = threadIdx.x;
145	
146	    bool is_q = (head_global < num_q_heads);
147	    int local_heads = is_q ? num_q_heads : num_kv_heads;
148	    int seq_len = is_q ? q_len : k_len;
149	    if (token >= seq_len) return;
150	
151	    int head_local = is_q ? head_global : (head_global - num_q_heads);
152	    if (head_local >= local_heads) return;
153	
154	    __nv_bfloat16* data = is_q ? q : k;
155	    int dim_stride = local_heads * head_dim;
156	    const __nv_bfloat16* norm_w = is_q ? q_norm_weight : k_norm_weight;
157	    int pos = (is_q ? q_start_pos : k_start_pos) + token;
158	    if (pos < 0 || pos >= cos_max_pos) __trap();
159	
160	    int offset = token * dim_stride + head_local * head_dim + d;
161	    float val = __bfloat162float(data[offset]);
162	
163	    float sq = warp_reduce_sum(val * val);
164	    int warp_id = d / WARP_SIZE;
165	    int lane_id = d % WARP_SIZE;
166	    int num_warps = blockDim.x / WARP_SIZE;  // head_dim / 32: 2 (dim 64) or 4 (dim 128)
167	    __shared__ float warp_sums[4];
168	    if (lane_id == 0) warp_sums[warp_id] = sq;
169	    __syncthreads();
170	
171	    __shared__ float s_inv_rms;
172	    if (warp_id == 0) {
173	        float v = (lane_id < num_warps) ? warp_sums[lane_id] : 0.0f;
174	        float total = warp_reduce_sum(v);
175	        if (lane_id == 0) s_inv_rms = rsqrtf(total / head_dim + eps);
176	    }
177	    __syncthreads();
178	
179	    __nv_bfloat16 normed = __float2bfloat16(val * s_inv_rms);
180	    float normed_f = __bfloat162float(normed) * __bfloat162float(norm_w[d]);
181	
182	    __shared__ __nv_bfloat16 smem[HEAD_DIM];
183	    smem[d] = __float2bfloat16(normed_f);
184	    __syncthreads();
185	
186	    int half = head_dim / 2;
187	    __nv_bfloat16 result;
188	    if (d < half) {
189	        float lo = __bfloat162float(smem[d]);
190	        float hi = __bfloat162float(smem[d + half]);
191	        float c = __bfloat162float(cos_cache[pos * head_dim + d]);
192	        float s = __bfloat162float(sin_cache[pos * head_dim + d]);
193	        float lo_cos = __bfloat162float(__float2bfloat16(lo * c));
194	        float hi_sin = __bfloat162float(__float2bfloat16(hi * s));
195	        result = __float2bfloat16(lo_cos - hi_sin);
196	    } else {
197	        int pair_d = d - half;
198	        float lo = __bfloat162float(smem[pair_d]);
199	        float hi = __bfloat162float(smem[d]);
200	        float c = __bfloat162float(cos_cache[pos * head_dim + pair_d]);
201	        float s = __bfloat162float(sin_cache[pos * head_dim + pair_d]);
202	        float lo_sin = __bfloat162float(__float2bfloat16(lo * s));
203	        float hi_cos = __bfloat162float(__float2bfloat16(hi * c));
204	        result = __float2bfloat16(lo_sin + hi_cos);
205	    }
206	
207	    data[offset] = result;
208	}
