324	int dflash_qk_norm_rope_cuda(
325	    __nv_bfloat16* q,
326	    __nv_bfloat16* k,
327	    const __nv_bfloat16* q_norm_weight,
328	    const __nv_bfloat16* k_norm_weight,
329	    const __nv_bfloat16* cos_cache,
330	    const __nv_bfloat16* sin_cache,
331	    int num_q_heads,
332	    int num_kv_heads,
333	    int head_dim,
334	    int q_len,
335	    int k_len,
336	    int q_start_pos,
337	    int k_start_pos,
338	    float rms_eps,
339	    int cos_max_pos,
340	    cudaStream_t stream
341	) {
342	    // One thread per dim element, whole warps only, and the shared buffers
343	    // (warp_sums[4], smem[HEAD_DIM]) are sized for head_dim <= 128. Serves
344	    // Qwen3 DFlash (head_dim 128) and the GLM5.2 DSpark drafter (head_dim 64).
345	    if (q == nullptr || k == nullptr || q_norm_weight == nullptr ||
346	        k_norm_weight == nullptr || cos_cache == nullptr || sin_cache == nullptr ||
347	        num_q_heads <= 0 || num_kv_heads <= 0 ||
348	        head_dim % WARP_SIZE != 0 || head_dim <= 0 || head_dim > HEAD_DIM ||
349	        q_len <= 0 || k_len <= 0 || q_start_pos < 0 || k_start_pos < 0 ||
350	        q_start_pos + q_len > cos_max_pos || k_start_pos + k_len > cos_max_pos) {
351	        return static_cast<int>(cudaErrorInvalidValue);
352	    }
353	
354	    dim3 grid(num_q_heads + num_kv_heads, q_len > k_len ? q_len : k_len);
355	    dflash_qk_norm_rope_kernel<<<grid, head_dim, 0, stream>>>(
356	        q, k, q_norm_weight, k_norm_weight, cos_cache, sin_cache,
357	        num_q_heads, num_kv_heads, head_dim, q_len, k_len,
358	        q_start_pos, k_start_pos, rms_eps, cos_max_pos);
359	    return static_cast<int>(cudaGetLastError());
360	}
