    uint32_t group_size = num_qo_heads / num_kv_heads;
    int64_t packed_qo_len = static_cast<int64_t>(total_seq_len) * group_size;
    return static_cast<int32_t>(FA2DetermineCtaTileQ(packed_qo_len, head_dim));
