7	// Always-on invariant check (unlike <cassert>, fires under -DNDEBUG too).
8	#define QK_ASSERT(cond)                                                       \
9	    do {                                                                      \
10	        if (!(cond)) {                                                        \
11	            std::fprintf(stderr, "%s:%d: QK invariant failed: %s\n",          \
12	                         __FILE__, __LINE__, #cond);                          \
