17	// ============================================================================
18	// Kernel 1: warp-per-token QK RMSNorm + RoPE (in-place on Q and K batches).
19	//
20	// One warp owns one (head, token); each lane holds 4 contiguous dims as a
21	// float2 bf16 load. RMSNorm reduces with a shuffle butterfly, RoPE exchanges
22	// the rotate-half partner with `__shfl_xor_sync(.., 16)` (lane^16 == dim±half),
23	// so there is no shared memory and QK_TOKENS_PER_BLOCK warps pack into one
24	// block. Hard-wired to head_dim == 128 (32 lanes × 4 dims, half == 16 lanes);
25	// the launcher asserts it.
26	//
27	// The kernel is DRAM-latency-bound at ~88% occupancy (ncu, sm_120), so the
28	// lever is memory-level parallelism per warp, not more warps: all four
29	// independent loads (q/k, norm_w, cos, sin) are issued UP FRONT so they
30	// overlap in flight. Writing them in dependency order (as the partner shuffle
31	// would suggest) lets the `__trap` pos-check fence cos/sin behind the reduce;
32	// hoisting by hand measured −5% duration / +3pt DRAM SOL on a 5090.
33	//
34	// `positions[token]` is each row's absolute RoPE position (the single source
35	// of truth): a request resuming from a cached prefix has non-contiguous
36	// positions and still rotates at its true offset.
37	// ============================================================================
38	#define QK_TOKENS_PER_BLOCK 4
39	__global__ void prefill_qk_norm_rope_warp_kernel(
40	    __nv_bfloat16* __restrict__ q,
41	    __nv_bfloat16* __restrict__ k,
42	    const __nv_bfloat16* __restrict__ q_norm_weight,
43	    const __nv_bfloat16* __restrict__ k_norm_weight,
44	    const __nv_bfloat16* __restrict__ cos_cache,
45	    const __nv_bfloat16* __restrict__ sin_cache,
46	    const int* __restrict__ positions,
47	    int num_q_heads, int num_kv_heads, int head_dim,
48	    int seq_len, int q_dim, int kv_dim,
49	    float eps, int cos_max_pos
50	) {
51	    const int head_global = blockIdx.x;
52	    const int token = blockIdx.y * QK_TOKENS_PER_BLOCK + threadIdx.y;
53	    if (token >= seq_len) return;
54	    const int lane = threadIdx.x;          // 0..31
55	    const int half = head_dim / 2;         // 64
56	
57	    const bool is_q = (head_global < num_q_heads);
58	    const int head_local = is_q ? head_global : (head_global - num_q_heads);
59	    __nv_bfloat16* data = is_q ? q : k;
60	    const int dim_stride = is_q ? q_dim : kv_dim;
61	    const __nv_bfloat16* norm_w = is_q ? q_norm_weight : k_norm_weight;
62	
63	    const int d0 = lane * 4;
64	    const int base = token * dim_stride + head_local * head_dim + d0;
65	
66	    // Issue every independent global load up front (each is one float2/LDG.64;
67	    // the 4 contiguous dims a lane needs are adjacent in memory).
68	    __nv_bfloat16 raw_bf[4];
69	    *reinterpret_cast<float2*>(raw_bf) = *reinterpret_cast<const float2*>(&data[base]);
70	    __nv_bfloat16 wb[4];
71	    *reinterpret_cast<float2*>(wb) = *reinterpret_cast<const float2*>(&norm_w[d0]);
72	    const int pos = __ldg(positions + token);
73	    if (pos < 0 || pos >= cos_max_pos) __trap();
74	    const bool low = (d0 < half);
75	    const int cbase = pos * head_dim + (low ? d0 : d0 - half);
76	    __nv_bfloat16 cb[4], sb[4];
77	    *reinterpret_cast<float2*>(cb) = *reinterpret_cast<const float2*>(&cos_cache[cbase]);
78	    *reinterpret_cast<float2*>(sb) = *reinterpret_cast<const float2*>(&sin_cache[cbase]);
79	
80	    float val[4];
81	    #pragma unroll
82	    for (int r = 0; r < 4; r++) val[r] = __bfloat162float(raw_bf[r]);
83	
84	    // RMSNorm sum of squares: 4-per-lane, then shuffle butterfly across the warp.
85	    float sq = 0.f;
86	    #pragma unroll
87	    for (int r = 0; r < 4; r++) sq += val[r] * val[r];
88	    #pragma unroll
89	    for (int o = WARP_SIZE / 2; o > 0; o >>= 1)
90	        sq += __shfl_xor_sync(0xffffffff, sq, o);
91	    const float inv_rms = rsqrtf(sq / head_dim + eps);
92	
93	    float normed[4];
94	    #pragma unroll
95	    for (int r = 0; r < 4; r++) {
96	        __nv_bfloat16 n = __float2bfloat16(val[r] * inv_rms);
97	        float nf = __bfloat162float(n) * __bfloat162float(wb[r]);
98	        normed[r] = __bfloat162float(__float2bfloat16(nf));
99	    }
100	
101	    // Rotate-half partner: lane^16 maps d0 <-> d0 ± half.
102	    float partner[4];
103	    #pragma unroll
104	    for (int r = 0; r < 4; r++)
105	        partner[r] = __shfl_xor_sync(0xffffffff, normed[r], 16);
106	
107	    __nv_bfloat16 out[4];
108	    #pragma unroll
109	    for (int r = 0; r < 4; r++) {
110	        float c = __bfloat162float(cb[r]);
111	        float s = __bfloat162float(sb[r]);
112	        if (low) {
113	            float lo_cos = __bfloat162float(__float2bfloat16(normed[r] * c));
114	            float hi_sin = __bfloat162float(__float2bfloat16(partner[r] * s));
115	            out[r] = __float2bfloat16(lo_cos - hi_sin);
116	        } else {
117	            float lo_sin = __bfloat162float(__float2bfloat16(partner[r] * s));
118	            float hi_cos = __bfloat162float(__float2bfloat16(normed[r] * c));
119	            out[r] = __float2bfloat16(lo_sin + hi_cos);
120	        }
121	    }
122	    *reinterpret_cast<float2*>(&data[base]) = *reinterpret_cast<float2*>(out);
123	}
