290	    const __nv_bfloat16* cos_cache,
291	    const __nv_bfloat16* sin_cache,
292	    const int* positions,                // [batch_size] per-request positions on GPU
293	    int num_q_heads,
294	    int num_kv_heads,
295	    int head_dim,
296	    int batch_size,
297	    float rms_eps,
298	    int cos_max_pos,
299	    cudaStream_t stream
300	) {
301	    int q_dim = num_q_heads * head_dim;
302	    int kv_dim = num_kv_heads * head_dim;
303	
304	    // blockIdx.y = batch index; positions[batch_idx] supplies each row's
305	    // absolute RoPE position (prefix-cache-hit suffixes rotate at their true
306	    // offset). The warp kernel is hard-wired to head_dim == 128 — the only
307	    // caller is Qwen3, whose head_dim is 128 under any TP degree (TP shards
308	    // head count, not head_dim). Anything else is a wiring bug, not a runtime
309	    // case to silently absorb.
310	    QK_ASSERT(head_dim == HEAD_DIM);
311	
312	    int tiles = (batch_size + QK_TOKENS_PER_BLOCK - 1) / QK_TOKENS_PER_BLOCK;
313	    dim3 grid(num_q_heads + num_kv_heads, tiles);
314	    dim3 block(WARP_SIZE, QK_TOKENS_PER_BLOCK);
315	    prefill_qk_norm_rope_warp_kernel<<<grid, block, 0, stream>>>(
316	        q, k, q_norm_weight, k_norm_weight,
317	        cos_cache, sin_cache, positions,
318	        num_q_heads, num_kv_heads, head_dim,
319	        /*seq_len=*/batch_size, q_dim, kv_dim,
320	        rms_eps, cos_max_pos
321	    );
322	}
323	
324	int dflash_qk_norm_rope_cuda(
325	    __nv_bfloat16* q,
326	    __nv_bfloat16* k,
327	    const __nv_bfloat16* q_norm_weight,
328	    const __nv_bfloat16* k_norm_weight,
329	    const __nv_bfloat16* cos_cache,
330	    const __nv_bfloat16* sin_cache,
331	    int num_q_heads,
332	    int num_kv_heads,
333	    int head_dim,
334	    int q_len,
335	    int k_len,
336	    int q_start_pos,
337	    int k_start_pos,
338	    float rms_eps,
339	    int cos_max_pos,
340	    cudaStream_t stream
341	) {
342	    // One thread per dim element, whole warps only, and the shared buffers
343	    // (warp_sums[4], smem[HEAD_DIM]) are sized for head_dim <= 128. Serves
344	    // Qwen3 DFlash (head_dim 128) and the GLM5.2 DSpark drafter (head_dim 64).
345	    if (q == nullptr || k == nullptr || q_norm_weight == nullptr ||
346	        k_norm_weight == nullptr || cos_cache == nullptr || sin_cache == nullptr ||
347	        num_q_heads <= 0 || num_kv_heads <= 0 ||
348	        head_dim % WARP_SIZE != 0 || head_dim <= 0 || head_dim > HEAD_DIM ||
349	        q_len <= 0 || k_len <= 0 || q_start_pos < 0 || k_start_pos < 0 ||
350	        q_start_pos + q_len > cos_max_pos || k_start_pos + k_len > cos_max_pos) {
351	        return static_cast<int>(cudaErrorInvalidValue);
352	    }
353	
354	    dim3 grid(num_q_heads + num_kv_heads, q_len > k_len ? q_len : k_len);
355	    dflash_qk_norm_rope_kernel<<<grid, head_dim, 0, stream>>>(
356	        q, k, q_norm_weight, k_norm_weight, cos_cache, sin_cache,
357	        num_q_heads, num_kv_heads, head_dim, q_len, k_len,
358	        q_start_pos, k_start_pos, rms_eps, cos_max_pos);
359	    return static_cast<int>(cudaGetLastError());
360	}
361	
362	// Plain RoPE (no QK-norm) for EAGLE-3. Launches eagle3_rope_kernel.
363	int eagle3_rope_cuda(
364	    __nv_bfloat16* q,
365	    __nv_bfloat16* k,
366	    const __nv_bfloat16* cos_cache,
367	    const __nv_bfloat16* sin_cache,
368	    int num_q_heads,
369	    int num_kv_heads,
370	    int head_dim,
371	    int q_len,
372	    int k_len,
373	    int q_start_pos,
374	    int k_start_pos,
375	    int cos_max_pos,
376	    cudaStream_t stream
377	) {
378	    if (q == nullptr || k == nullptr || cos_cache == nullptr || sin_cache == nullptr ||
379	        num_q_heads <= 0 || num_kv_heads <= 0 || head_dim != HEAD_DIM ||
380	        q_len <= 0 || k_len <= 0 || q_start_pos < 0 || k_start_pos < 0 ||
381	        q_start_pos + q_len > cos_max_pos || k_start_pos + k_len > cos_max_pos) {
382	        return static_cast<int>(cudaErrorInvalidValue);
383	    }
384	
385	    dim3 grid(num_q_heads + num_kv_heads, q_len > k_len ? q_len : k_len);
386	    eagle3_rope_kernel<<<grid, head_dim, 0, stream>>>(
387	        q, k, cos_cache, sin_cache,
388	        num_q_heads, num_kv_heads, head_dim, q_len, k_len,
389	        q_start_pos, k_start_pos, cos_max_pos);
390	    return static_cast<int>(cudaGetLastError());
391	}
392	
393	} // extern "C"
394

